//! Integration tests mirroring the 4Leibniz Python test-suite scenarios
//! for the modules ported into `archon_kernel`:
//! * `tests/test_phase7.py` — BFT decision + incentive accounting
//! * `tests/test_phase8.py` — multi-prover aggregation
//! * `counterexample.py` semantics ( exercised via golden outputs
//!   generated by running the Python reference itself )
//! * `zk_verify.py` gate behavior (shape bounds / unavailable key)

use archon_kernel::bft::{decide, BFTPeer, BFTVote};
use archon_kernel::counterexample::{find, Claim, Premise};
use archon_kernel::epistemic::{taint_of, Status};
use archon_kernel::multiprover::{aggregate, ProofReport};
use archon_kernel::zk_verify::{verify_groth16, Groth16Verifier, VerifyStatus};
use serde_json::{json, Value};

#[test]
fn phase7_bft_scenarios() {
    let peers: Vec<BFTPeer> = (0..4).map(|i| BFTPeer::new(format!("n{}", i))).collect();
    let honest: Vec<BFTVote> = (0..4)
        .map(|i| BFTVote::new(format!("n{}", i), "p", "proven"))
        .collect();
    let result = decide(&peers, &honest, 1, 2.0 / 3.0);
    assert!(result.accepted);
    assert_eq!(result.incentives.iter().map(|i| i.delta).sum::<i64>(), 4);

    let equivocating = vec![
        BFTVote::new("n0", "p", "proven"),
        BFTVote::new("n0", "p", "open"),
        BFTVote::new("n1", "p", "proven"),
        BFTVote::new("n2", "p", "proven"),
        BFTVote::new("n3", "p", "proven"),
    ];
    let result = decide(&peers, &equivocating, 1, 2.0 / 3.0);
    assert!(!result.accepted);
    assert_eq!(result.equivocations, vec!["n0".to_string()]);
}

#[test]
fn phase8_multiprover_scenarios() {
    let reports = vec![
        ProofReport::with_flags("a", "d", "proven", true, true),
        ProofReport::with_flags("b", "d", "proven", true, true),
        ProofReport::with_flags("c", "d", "proven", false, true),
    ];
    let result = aggregate(&reports, 2, true);
    assert!(result.accepted);
    assert_eq!(result.independent_kernel_reports, 2);

    let split = vec![
        ProofReport::with_flags("a", "d", "proven", true, false),
        ProofReport::with_flags("b", "other", "derived", true, false),
    ];
    let result = aggregate(&split, 2, true);
    assert!(!result.accepted);
    assert_eq!(result.dissent.len(), 1);
}

#[test]
fn counterexample_golden_certificates() {
    let claim = Claim::new("Gt", vec![Premise::new("x >= y")], "x > y");
    let cert = find(&claim, 3);
    assert_eq!(cert.outcome, "refuted");
    assert_eq!(
        cert.fingerprint,
        "87cf2473ebb40c8ce85a43321ef9100035aad16e8610628b6b60649b1f7a01e8"
    );

    let sound = Claim::new(
        "Trans",
        vec![Premise::new("x >= y"), Premise::new("y >= z")],
        "x >= z",
    );
    let cert = find(&sound, 3);
    assert_eq!(cert.outcome, "no-witness");
    assert_eq!(cert.fingerprint, "");
}

#[test]
fn taint_law_agrees_with_multiprover_minimum() {
    // The accepted multiprover status equals the epistemic taint of
    // the winning reports' statuses (SAMO section 3.2 bind law).
    let reports = vec![
        ProofReport::with_flags("a", "d", "proven", true, true),
        ProofReport::with_flags("b", "d", "axiomatic", true, false),
    ];
    let result = aggregate(&reports, 2, true);
    let expected = taint_of(&[Status::Proven, Status::Axiomatic]);
    assert_eq!(result.status, expected.unwrap().name());
}

struct AcceptingBackend;
impl Groth16Verifier for AcceptingBackend {
    fn verify(
        &self,
        _proof: &Value,
        _signals: &[Value],
        _key: &Value,
    ) -> Result<(bool, VerifyStatus, String), String> {
        Ok((true, VerifyStatus::Verified, "OK".into()))
    }
}

#[test]
fn zk_gate_end_to_end_with_stub_backend() {
    let proof = json!({"pi_a": ["1"], "pi_b": [["1"]], "pi_c": ["1"], "protocol": "groth16"});
    let key = json!({"protocol": "groth16"});
    let out = verify_groth16(&proof, &[json!(42)], Some(&key), &AcceptingBackend);
    assert!(out.verified);
    assert_eq!(out.status, VerifyStatus::Verified);

    let out = verify_groth16(&proof, &[json!(42)], None, &AcceptingBackend);
    assert_eq!(out.status, VerifyStatus::Unavailable);
}
